 "content": "def transform(grid):
    """Extend a solid 2-rectangle along its rows and columns, away from markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    # A marker on one side of the rectangle sends the 2-ray through the
    # rectangle and out the opposite side. With no marker, extend both ways.
    for r in range(r0, r1 + 1):
        left_marker = any(grid[r][c] not in (0, 2) for c in range(c0))
        right_marker = any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w))
        if not left_marker:
            for c in range(0, c0):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not right_marker:
            for c in range(c1 + 1, w):
                if grid[r][c] == 0:
                    out[r][c] = 2

    for c in range(c0, c1 + 1):
        top_marker = any(grid[r][c] not in (0, 2) for r in range(r0))
        bottom_marker = any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h))
        if not top_marker:
            for r in range(0, r0):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not bottom_marker:
            for r in range(r1 + 1, h):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
